HRESULT WINAPI CryptXmlGetStatus( HCRYPTXML handle, CRYPT_XML_STATUS *status )
{
    struct object *obj = (struct object *)handle;

    TRACE( "handle %p, status %p\n", handle, status );

    if (!obj || !status) return E_INVALIDARG;

    *status = obj->status;
    return S_OK;
}

